INSERT INTO "public"."questions" ("id", "type", "prompt") VALUES ('0169b76f-b6ae-4332-af0b-f622e783263d', 'Essay', 'Some believe that learning history is unnecessary because we should focus on modern skills. Discuss both views and give your opinion.'), ('040b14cc-b162-45ed-aff1-9b05e82488eb', 'Essay', 'Some believe that technological progress brings more harm than good. Discuss both views and give your opinion.'), ('0d95c8f1-c7b3-42b1-9b73-f166a6dfc8d5', 'Essay', 'Films and television programs often show strong violence. Some people think violent media should be censored while others think they are harmless relaxation. Discuss both views and give your opinion.'), ('13b4ae0f-d191-40c7-afd9-c7fa2af0e73d', 'Essay', 'Some people believe that owning homes is better than renting, while others think renting is more practical. Discuss both views and give your opinion.'), ('1a065f90-c4cd-4745-aa57-8d31bc6ced1b', 'Essay', 'Some people think work and career are the most important things in life, while others think family and relationships are more important. Discuss both views and give your opinion.'), ('33e15bfd-7c70-4045-be8e-96a76819b9b4', 'Essay', 'Some people think that protecting the environment should be a higher priority than economic growth. Discuss both views and give your opinion.'), ('3700822b-bfc4-4cfe-ab38-7b4502554413', 'Essay', 'Human activities have caused many environmental problems. Some people think governments should take responsibility while others think individuals should take action. Discuss both views and give your opinion.'), ('3aa9ffc8-32b6-4569-8117-017bd49f367e', 'Essay', 'Some people think advertising has a negative effect on society while others think it is informative and beneficial. Discuss both views and give your opinion.'), ('40043cdd-50c7-467d-a62c-34f20556a07d', 'Essay', 'Some people buy more than they need because they want to show others what they have. To what extent do you agree or disagree?'), ('48293ee9-35a4-4f3a-b308-a01456a007e5', 'Essay', 'Some people say children should learn practical skills at school while others believe academic subjects are more important. Discuss both views and give your own opinion.'), ('4aec6472-71d1-4104-b511-b120548b8c30', 'Essay', 'Some people think that increasing the cost of fuel is the most effective way to solve global environmental problems. To what extent do you agree or disagree?'), ('5d1e48d3-bf6a-4758-80cb-ec0de7664a28', 'Essay', 'Some people believe we should preserve old buildings and historic sites, while others think new buildings are more important. Discuss both views and give your own opinion.'), ('6aabd4e1-b3dc-44e2-b23c-f4d12cf12fb0', 'Essay', 'Some people think that museums and galleries should be free to everyone, while others argue they should charge for entry. Discuss both views and give your opinion.'), ('6c160bb6-467f-4e0d-94d7-a6d8ef0c7efb', 'Essay', 'Some people believe that celebrities have a negative influence on young people, while others think they can be positive role models. Discuss both views and give your opinion.'), ('75a51dd9-52c8-4c50-8bf2-9ebbede87be3', 'Essay', 'Some people think that the best way to travel is by car while others prefer public transport. Discuss both views and give your own opinion.'), ('79a1150f-ff27-4f5a-8b96-91954848cbaa', 'Essay', 'Some people argue that governments should increase taxes on unhealthy foods to improve public health. To what extent do you agree or disagree?'), ('8bfa8e34-9658-4203-91a4-c097d9a37929', 'Essay', 'Movies and TV shows sometimes contain material that should be censored. Others say they are harmless relaxation. Discuss both these views and give your own opinion.'), ('8d13f621-e74d-4964-9d58-749f7e86014f', 'Essay', 'Films and computers games containing violence are popular. Some people say they have negative effect on society and should be banned. Others say they are just harmless relaxation. Discuss both views and give your opinion.'), ('9d6eae01-b6fd-4cbd-bd92-c3ffd4a78cdb', 'Essay', 'Only 20% of Tech Jobs are Held by Women. What problems do women face that prevent them from getting these jobs and what must be done to change this situation.'), ('adfec4f8-f10e-4c8f-a50e-a09698777286', 'Essay', 'Some people think increasing the cost of fuel is the best way to address global environmental problems. To what extent do you agree or disagree?'), ('b327defc-4a48-4add-a410-e04f8d75ef6b', 'Essay', 'Some people believe that city life is better because it offers more opportunities, while others prefer the peace of rural life. Discuss both views and give your opinion.'), ('bbd52e34-d818-4c4f-aadd-45227d789094', 'Essay', 'Some people think that online learning is as effective as traditional classroom learning. Discuss both views and give your opinion.'), ('bdb2d11b-c62f-4a9a-9852-ba36884d24af', 'Essay', 'Some people think that governments should provide free education for all, while others think students should pay. Discuss both views and give your opinion.'), ('c5577e55-c709-43be-b664-d8cac30e7d75', 'Essay', 'Nowadays, young people are more likely to start their own businesses than work for large companies. Discuss both views and give your own opinion.'), ('d792bf0f-a95f-4eb4-a1b2-2034a55433b6', 'Essay', 'In many countries, people are living longer than in the past. What are the causes of this trend and what problems does it create for individuals and society? Give reasons and make suggestions.'), ('dd64932b-0f72-497c-8691-46c5b8a170be', 'Essay', 'Many people argue that in order to improve educational quality, high school students are encouraged to make comments or even criticism on their teachers. Other thinks it will lead to loss of respect and discipline in the classroom. Discuss both views'), ('e62b5463-aabc-4d59-9487-8919ce500766', 'Essay', 'Some people think that governments should increase the cost of fuel to reduce pollution, while others oppose this. To what extent do you agree or disagree?'), ('f4893b7b-cf71-495c-8a72-d88cea20a35f', 'Essay', 'Every day more people visit historic buildings and places of interest. Why do you think this is happening? And how can we solve this problem?'), ('f93b489f-3860-4805-918e-d543466b1fc1', 'Essay', 'Some people think that the government should invest more in public transportation, while others think investing in roads is more important. Discuss both views and give your opinion.'), ('fc38bea4-054d-42d4-87f0-2d939dd5df46', 'Essay', 'Some believe that teachers and lecturers should be paid according to their performance while others think equal pay is better. Discuss both views and give your opinion.');